    let maskedValue = value;
    if (value && value.length > 20) {
        const firstPart = value.substring(0, 10);
        const lastPart = value.substring(value.length - 5);
        maskedValue = `${firstPart}...${lastPart}`;
    }
    console.log(`${key}: ${maskedValue}`);
});

